import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Sharing a view","description":"Share a view as a private link, via QR code, or embedded.","frontmatter":{"title":"Sharing a view","description":"Share a view as a private link, via QR code, or embedded."},"headers":[],"relativePath":"en/ansichten/ansicht-teilen.md","filePath":"en/ansichten/ansicht-teilen.md","lastUpdated":1787319236000}'),r={name:"en/ansichten/ansicht-teilen.md"};function o(s,e,l,h,d,c){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="sharing-a-view" tabindex="-1">Sharing a view <a class="header-anchor" href="#sharing-a-view" aria-label="Permalink to &quot;Sharing a view&quot;">​</a></h1><p>Every view can be shared via a link — with people who don&#39;t have an ApptiveGrid account.</p><h2 id="creating-a-link" tabindex="-1">Creating a link <a class="header-anchor" href="#creating-a-link" aria-label="Permalink to &quot;Creating a link&quot;">​</a></h2><p>Click <strong>Share</strong>. As long as there&#39;s no link yet, it says:</p><blockquote><p><strong>Create a shareable link to the view</strong><em>You can send the link to anyone or embed it in a website.</em></p></blockquote><p>After creating it:</p><blockquote><p><strong>This view is being shared via a private link</strong><em>This link makes the data in this view visible.</em></p></blockquote><div class="danger custom-block"><p class="custom-block-title">Public by default</p><p>Without an additional restriction, <strong>anyone with the link</strong> can open the view. The link isn&#39;t guessable, but it&#39;s unprotected — if it&#39;s forwarded, it keeps working there too.</p><p>Decide on the access restriction <strong>before</strong> distributing it. → <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></p></div><h2 id="what-recipients-see" tabindex="-1">What recipients see <a class="header-anchor" href="#what-recipients-see" aria-label="Permalink to &quot;What recipients see&quot;">​</a></h2><p><strong>Exactly what&#39;s visible in this view</strong> — with the filter, sort, grouping, and the visible columns.</p><div class="warning custom-block"><p class="custom-block-title">Filters provide visual privacy, not access control</p><p>Hidden columns and filters reduce what gets through. But for confidential data, don&#39;t rely on that alone: combine it with an access restriction, or don&#39;t put sensitive data in the same Grid in the first place.</p></div><div class="tip custom-block"><p class="custom-block-title">A dedicated view for sharing</p><p>Don&#39;t share your working view. Create a copy (<em>Duplicate view</em>), hide everything internal, filter to what&#39;s needed — and share that. This way, what you&#39;re sharing doesn&#39;t accidentally change along with your working view.</p></div><h2 id="allowing-new-entries-via-the-view" tabindex="-1">Allowing new entries via the view <a class="header-anchor" href="#allowing-new-entries-via-the-view" aria-label="Permalink to &quot;Allowing new entries via the view&quot;">​</a></h2><p>The dialog offers:</p><blockquote><p><em>Optionally choose a form to allow the creation of new entries.</em></p></blockquote><p>If you choose a <a href="/en/formulare/formular-erstellen">form</a>, recipients can create new entries. Without a form, no new entry can be created via the link.</p><div class="tip custom-block"><p class="custom-block-title">Editing existing entries depends on the role</p><p>Whether a person can edit existing entries in the shared view isn&#39;t decided by the form, but by their own permission: if they&#39;re signed in to ApptiveGrid when opening the link and have a role with edit rights on the Grid, they can edit directly in the view. Without signing in, or without a matching role, they&#39;re limited to reading.</p></div><h2 id="qr-code-and-mobile-app" tabindex="-1">QR code and mobile app <a class="header-anchor" href="#qr-code-and-mobile-app" aria-label="Permalink to &quot;QR code and mobile app&quot;">​</a></h2><p>The share dialog has several tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th></tr></thead><tbody><tr><td><strong>Link</strong></td><td>Address to <strong>Copy</strong>, <strong>Open link</strong>, <strong>Remove</strong></td></tr><tr><td><strong>QR Code</strong></td><td>Code to scan</td></tr><tr><td><strong>Open in App</strong></td><td>Add the view to the mobile app</td></tr></tbody></table><p>The subtitle reads <em>Share your view with others and work from anywhere.</em></p><h2 id="restricting-access" tabindex="-1">Restricting access <a class="header-anchor" href="#restricting-access" aria-label="Permalink to &quot;Restricting access&quot;">​</a></h2><p>For views, the <strong>username and password</strong> model applies:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Everyone</strong></td><td><em>Anyone with the link can access it</em></td></tr><tr><td><strong>With credentials</strong></td><td><em>Access only with a username and password</em></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Credentials are visible only once</p><blockquote><p><em>For security reasons, you can&#39;t view the username and password again later. However, you can reset them at any time.</em></p></blockquote><p>Write both down immediately.</p></div><p>A different model applies to <strong>forms</strong> — the comparison is under <a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a>.</p><h2 id="sharing-a-single-entry" tabindex="-1">Sharing a single entry <a class="header-anchor" href="#sharing-a-single-entry" aria-label="Permalink to &quot;Sharing a single entry&quot;">​</a></h2><p>Instead of the whole view, you can also share a <strong>single entry</strong>: via the row menu&#39;s <strong>Share entry</strong>. This requires a form on this Grid.</p><p>→ <a href="/en/formulare/eintraege-bearbeiten">Editing entries via a form</a></p><h2 id="embedding-a-view-in-a-page" tabindex="-1">Embedding a view in a page <a class="header-anchor" href="#embedding-a-view-in-a-page" aria-label="Permalink to &quot;Embedding a view in a page&quot;">​</a></h2><p>Within ApptiveGrid, you embed a view into a <a href="/en/seiten/was-sind-seiten">page</a> via the <strong>Grid View</strong> block. There you can also control whether visitors can search, filter, export, and open entries.</p><p>For a portal, this is usually the better route than a plain view link: you can combine text, explanations, and multiple views.</p><p>→ <a href="/en/seiten/auswertungen">Embedding views and reports</a></p><h2 id="removing-a-link" tabindex="-1">Removing a link <a class="header-anchor" href="#removing-a-link" aria-label="Permalink to &quot;Removing a link&quot;">​</a></h2><p>Via <strong>Remove</strong> in the share dialog, or in the Space&#39;s <a href="/en/zusammenarbeit/externe-links">links overview</a>.</p><p>A removed link stops working immediately — even for people who saved it.</p><div class="warning custom-block"><p class="custom-block-title">Deleting the view invalidates links</p><p>If you delete the view itself, all links pointing to it and the forms created from it stop working. ApptiveGrid warns about this when deleting.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/zusammenarbeit/zugriff-beschraenken">Access to shared content</a></li><li><a href="/en/zusammenarbeit/externe-links">External links overview</a></li><li><a href="/en/ansichten/spalten-verwalten">Manage columns</a></li></ul>',39)])])}const m=t(r,[["render",o]]);export{g as __pageData,m as default};
